// Same proven pattern as the Code Reviewer / Failure Analysis workflows.
const item = $input.item;
const binary = item.binary || {};
const keys = Object.keys(binary);
const chatInput = item.json.chatInput || '';

return keys.map((key) => ({
  json: { fileName: binary[key].fileName || key, chatInput },
  binary: { data: binary[key] }
}));

// Same parsing logic as the Failure Analysis workflow: flattens all tests
// across nested suites, prefers a "flaky" test, else the first "unexpected"
// (consistently-failing) test, and builds a human-readable evidence summary.
const text = $json.data ?? $json.text ?? $json.fileText ?? '';

let report;
try {
  report = JSON.parse(text);
} catch (e) {
  return [{
    json: {
      noFailureFound: true,
      evidenceSummary: 'The uploaded file is not valid JSON. Please upload a Playwright JSON reporter output file (e.g. results.json).'
    }
  }];
}

function collectTests(suites, parentFile, out) {
  for (const suite of (suites || [])) {
    const currentFile = suite.file || parentFile;
    for (const spec of (suite.specs || [])) {
      for (const test of (spec.tests || [])) {
        out.push({
          title: spec.title,
          file: currentFile,
          projectName: test.projectName,
          status: test.status,
          results: (test.results || []).map((r) => ({
            retry: r.retry,
            status: r.status,
            duration: r.duration,
            errorMessage: (r.error && r.error.message) || (r.errors && r.errors[0] && r.errors[0].message) || null,
            errorStack: (r.error && r.error.stack) || (r.errors && r.errors[0] && r.errors[0].stack) || null
          }))
        });
      }
    }
    collectTests(suite.suites, currentFile, out);
  }
  return out;
}

const allTests = collectTests(report.suites, null, []);

let target = allTests.find((t) => t.status === 'flaky');
if (!target) target = allTests.find((t) => t.status === 'unexpected');

if (!target) {
  return [{
    json: {
      noFailureFound: true,
      evidenceSummary: 'No failing or flaky test was found in the uploaded report - every test passed on its first attempt. Nothing to summarize.'
    }
  }];
}

let evidenceSummary = `Test: ${target.title}\nFile: ${target.file}\nProject: ${target.projectName}\nPlaywright's final computed status for this test: ${target.status}\n\nAttempt-by-attempt results:\n`;

target.results.forEach((r) => {
  evidenceSummary += `- Retry ${r.retry}: ${r.status} (duration ${r.duration}ms)`;
  if (r.errorMessage) evidenceSummary += `\n  Error message: ${r.errorMessage}`;
  evidenceSummary += `\n`;
});

return [{
  json: {
    noFailureFound: false,
    testTitle: target.title,
    filePath: target.file,
    evidenceSummary
  }
}];

const result = $json.output;

let md = `### Failure Analysis Report\n\n`;
md += `**Test:** ${result.testTitle}\n`;
md += `**File:** ${result.filePath}\n\n`;
md += `**Classification:** ${result.classification}\n`;
md += `**Confidence:** ${result.confidence}\n\n`;
md += `**Evidence Signals Cited:**\n`;
for (const sig of (result.evidenceSignals || [])) md += `- ${sig}\n`;
md += `\n**Reasoning:** ${result.reasoning}\n\n`;

const recommendations = {
  Flaky: 'Recommend quarantining/stabilizing this test (e.g. a proper wait or retry strategy) - do NOT file a product bug for this.',
  DataIssue: 'Recommend fixing or resetting the underlying test data/fixtures - this is not a product or automation code defect.',
  EnvironmentIssue: 'Recommend checking test environment/infrastructure health before re-running - this is not a product or automation code defect.'
};

md += `**Why no bug was drafted:** This failure was classified as "${result.classification}", not a defect in the application or the automation code. ${recommendations[result.classification] || ''}`;

return [{ json: { output: md } }];

const bug = $('Bug Draft Generator Agent').item.json.output;
const analysis = $('AI Failure Analysis Agent').item.json.output;

let description = `*Bug Type:* ${bug.bugType}\n\n`;
description += `*Steps to Reproduce:*\n${bug.stepsToReproduce}\n\n`;
description += `*Expected Result:*\n${bug.expectedResult}\n\n`;
description += `*Actual Result:*\n${bug.actualResult}\n\n`;
description += `*Severity:* ${bug.severity} - ${bug.severityJustification}\n\n`;
description += `*Failure Classification:* ${analysis.classification} (confidence: ${analysis.confidence})\n`;
description += `*Classification Evidence:*\n`;
for (const sig of (analysis.evidenceSignals || [])) {
  description += `- ${sig}\n`;
}
description += `\n_This bug was drafted automatically from a Playwright test failure, classified and summarized by AI, and reviewed by a human before creation._`;

return [{
  json: {
    title: bug.title,
    bugType: bug.bugType,
    description,
    stepsToReproduce: bug.stepsToReproduce,
    expectedResult: bug.expectedResult,
    actualResult: bug.actualResult,
    severity: bug.severity,
    severityJustification: bug.severityJustification,
    testTitle: analysis.testTitle,
    filePath: analysis.filePath
  }
}];

const created = $input.item.json;
const payload = $('Prepare Jira Payload').item.json;
const bugKey = created.key || created.id || 'UNKNOWN';

let md = `**Decision:** Approved\n\n**New Bug Created:** ${bugKey}\n\n`;
md += `**Bug Type:** ${payload.bugType}\n\n`;
md += `**Title:** ${payload.title}\n\n`;
md += `**Severity:** ${payload.severity}\n\n`;
md += `${payload.description}`;

return [{ json: { output: md, decision: 'Approved', bugKey } }];

const payload = $('Prepare Jira Payload').item.json;

let md = `**Decision:** Rejected\n\n`;
md += `The drafted bug report for "${payload.title}" was rejected during human review. No issue was created in Jira.\n\n`;
md += `**Bug Type:** ${payload.bugType}\n\n`;
md += `**Drafted Severity:** ${payload.severity}\n\n`;
md += `_To create this bug, re-run the workflow with a corrected or more detailed failure report._`;

return [{ json: { output: md, decision: 'Rejected' } }];
